package dev.nymii.legacysmpcore.events;

import dev.nymii.legacysmpcore.Main;
import net.kyori.adventure.text.Component;
import org.bukkit.BanList;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.PlayerDeathEvent;

public class DeathHandler implements Listener {

    @EventHandler
    public void onPlayerDeath(PlayerDeathEvent event) {
        Player deadPlayer = event.getEntity();
        Location deathLocation = deadPlayer.getLocation();

        event.deathMessage(null);

        // Laisse une tombe indestructible à l'emplacement de la mort.
        Main.getInstance().getGraveManager().createGrave(deadPlayer, deathLocation);

        Bukkit.getBanList(BanList.Type.PROFILE).addBan(
            deadPlayer.getName(),
            "You have perished. You have left your mark on the world.\n" +
                    "\n" +
                    "Thank you for playing on LegacySMP.\n",
            null,
            null
        );

        deadPlayer.kick(Component.empty());
    }

}

package dev.nymii.legacysmpcore.events;

import dev.nymii.legacysmpcore.Main;
import net.kyori.adventure.text.Component;
import org.bukkit.BanList;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.PlayerDeathEvent;

public class DeathHandler implements Listener {

    @EventHandler
    public void onPlayerDeath(PlayerDeathEvent event) {
        Player deadPlayer = event.getEntity();
        Location deathLocation = deadPlayer.getLocation();

        event.deathMessage(null);

        // Laisse une tombe indestructible à l'emplacement de la mort.
        Main.getInstance().getGraveManager().createGrave(deadPlayer, deathLocation);

        Bukkit.getBanList(BanList.Type.PROFILE).addBan(
            deadPlayer.getName(),
            """
            ☠ Your story has come to an end. ☠

            Death is final here — but your legacy remains.
            A grave now marks the place where you fell.

            Thank you for the journey on LegacySMP.""",
            null,
            null
        );

        deadPlayer.kick(Component.empty());
    }

}

package dev.nymii.legacysmpcore.managers;

import dev.nymii.legacysmpcore.Main;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.scheduler.BukkitTask;
import org.bukkit.scoreboard.Scoreboard;
import org.bukkit.scoreboard.Team;

import java.util.HashMap;
import java.util.Map;

public class NametagVisibilityManager {

    private static final double VISIBILITY_RANGE = 15.0;
    private static final long UPDATE_INTERVAL = 20L; // 1 second
    private BukkitTask updateTask;
    private final Main plugin;
    private final Map<String, Team> playerTeams = new HashMap<>();

    public NametagVisibilityManager(Main plugin) {
        this.plugin = plugin;
    }

    public void start() {
        updateTask = Bukkit.getScheduler().runTaskTimer(plugin, this::updateNametagVisibility, 0L, UPDATE_INTERVAL);
    }

    public void stop() {
        if (updateTask != null) {
            updateTask.cancel();
            updateTask = null;
        }
    }

    public void setupPlayer(Player player) {
        Scoreboard scoreboard = Bukkit.getScoreboardManager().getMainScoreboard();
        String teamName = "player_" + player.getUniqueId().toString().substring(0, 8);

        Team team = scoreboard.getTeam(teamName);
        if (team == null) {
            team = scoreboard.registerNewTeam(teamName);
        }

        if (!team.hasEntry(player.getName())) {
            team.addEntry(player.getName());
        }

        team.setOption(Team.Option.NAME_TAG_VISIBILITY, Team.OptionStatus.NEVER);
        playerTeams.put(player.getUniqueId().toString(), team);
    }

    public void removePlayer(Player player) {
        Scoreboard scoreboard = Bukkit.getScoreboardManager().getMainScoreboard();
        String teamName = "player_" + player.getUniqueId().toString().substring(0, 8);
        Team team = scoreboard.getTeam(teamName);

        if (team != null) {
            team.removeEntry(player.getName());
            if (team.getEntries().isEmpty()) {
                team.unregister();
            }
        }

        playerTeams.remove(player.getUniqueId().toString());
    }

    private void updateNametagVisibility() {
        Player[] players = Bukkit.getOnlinePlayers().toArray(new Player[0]);

        for (Player player1 : players) {
            Team team1 = playerTeams.get(player1.getUniqueId().toString());
            if (team1 == null) continue;

            boolean shouldShow = false;

            // < 15 blocs
            for (Player player2 : players) {
                if (player1 != player2 && isNearby(player1, player2)) {
                    shouldShow = true;
                    break;
                }
            }

            Team.OptionStatus currentStatus = team1.getOption(Team.Option.NAME_TAG_VISIBILITY);
            Team.OptionStatus desiredStatus = shouldShow ? Team.OptionStatus.ALWAYS : Team.OptionStatus.NEVER;

            if (currentStatus != desiredStatus) {
                team1.setOption(Team.Option.NAME_TAG_VISIBILITY, desiredStatus);
            }
        }
    }

    // range checker
    private boolean isNearby(Player player1, Player player2) {
        if (!player1.getWorld().equals(player2.getWorld())) {
            return false;
        }

        double distance = player1.getLocation().distance(player2.getLocation());
        return distance <= VISIBILITY_RANGE;
    }
}

package dev.nymii.legacysmpcore.managers;

import dev.nymii.legacysmpcore.Main;
import io.papermc.paper.threadedregions.scheduler.ScheduledTask;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.scoreboard.Scoreboard;
import org.bukkit.scoreboard.Team;

import java.util.HashMap;
import java.util.Map;

public class NametagVisibilityManager {

    private static final double VISIBILITY_RANGE = 15.0;
    private static final long UPDATE_INTERVAL = 20L; // 1 second
    private ScheduledTask updateTask;
    private final Main plugin;
    private final Map<String, Team> playerTeams = new HashMap<>();

    public NametagVisibilityManager(Main plugin) {
        this.plugin = plugin;
    }

    public void start() {
        // Folia: le scheduler Bukkit classique n'est pas supporté, on utilise le GlobalRegionScheduler.
        // Le délai initial doit être >= 1 tick sur Folia.
        updateTask = Bukkit.getGlobalRegionScheduler()
                .runAtFixedRate(plugin, task -> updateNametagVisibility(), 1L, UPDATE_INTERVAL);
    }

    public void stop() {
        if (updateTask != null) {
            updateTask.cancel();
            updateTask = null;
        }
    }

    public void setupPlayer(Player player) {
        Scoreboard scoreboard = Bukkit.getScoreboardManager().getMainScoreboard();
        String teamName = "player_" + player.getUniqueId().toString().substring(0, 8);

        Team team = scoreboard.getTeam(teamName);
        if (team == null) {
            team = scoreboard.registerNewTeam(teamName);
        }

        if (!team.hasEntry(player.getName())) {
            team.addEntry(player.getName());
        }

        team.setOption(Team.Option.NAME_TAG_VISIBILITY, Team.OptionStatus.NEVER);
        playerTeams.put(player.getUniqueId().toString(), team);
    }

    public void removePlayer(Player player) {
        Scoreboard scoreboard = Bukkit.getScoreboardManager().getMainScoreboard();
        String teamName = "player_" + player.getUniqueId().toString().substring(0, 8);
        Team team = scoreboard.getTeam(teamName);

        if (team != null) {
            team.removeEntry(player.getName());
            if (team.getEntries().isEmpty()) {
                team.unregister();
            }
        }

        playerTeams.remove(player.getUniqueId().toString());
    }

    private void updateNametagVisibility() {
        Player[] players = Bukkit.getOnlinePlayers().toArray(new Player[0]);

        for (Player player1 : players) {
            Team team1 = playerTeams.get(player1.getUniqueId().toString());
            if (team1 == null) continue;

            boolean shouldShow = false;

            // < 15 blocs
            for (Player player2 : players) {
                if (player1 != player2 && isNearby(player1, player2)) {
                    shouldShow = true;
                    break;
                }
            }

            Team.OptionStatus currentStatus = team1.getOption(Team.Option.NAME_TAG_VISIBILITY);
            Team.OptionStatus desiredStatus = shouldShow ? Team.OptionStatus.ALWAYS : Team.OptionStatus.NEVER;

            if (currentStatus != desiredStatus) {
                team1.setOption(Team.Option.NAME_TAG_VISIBILITY, desiredStatus);
            }
        }
    }

    // range checker
    private boolean isNearby(Player player1, Player player2) {
        if (!player1.getWorld().equals(player2.getWorld())) {
            return false;
        }

        double distance = player1.getLocation().distance(player2.getLocation());
        return distance <= VISIBILITY_RANGE;
    }
}

package dev.nymii.legacysmpcore.events;

import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.AsyncPlayerChatEvent;

public class SocialHandler implements Listener {

    @EventHandler
    public void onPlayerSendMessage(AsyncPlayerChatEvent event) {
        event.setCancelled(true);
        event.getPlayer().sendMessage("§cThe chat is disabled, to talk please use VoiceChat Mod.");
    }
}

package dev.nymii.legacysmpcore.events;

import io.papermc.paper.event.player.AsyncChatEvent;
import net.kyori.adventure.text.Component;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;

public class SocialHandler implements Listener {

    @EventHandler
    public void onPlayerSendMessage(AsyncChatEvent event) {
        event.setCancelled(true);
        event.getPlayer().sendMessage(Component.text("The chat is disabled, to talk please use VoiceChat Mod."));
    }
}
